//! Byte-for-byte parity with the reference kepubify.
//!
//! `parity_with_kepubify` converts every fixture in `tests/parity/cases` and
//! compares each entry with the output kepubify produced for it
//! (`tests/parity/expected`, regenerated by `tests/parity/update.sh`).
//!
//! `parity_with_kepubify_on_corpus` does the same live on real books:
//! `KEPUBIFY=/path/to/kepubify KEPUB_CORPUS=/path/to/epubs cargo test -p relio-kepub --test parity -- --ignored`

use std::collections::BTreeMap;
use std::fs;
use std::io::{Cursor, Read, Write};
use std::path::{Path, PathBuf};
use std::process::Command;

use relio_kepub::{Charset, Options, convert_with};
use zip::write::SimpleFileOptions;
use zip::{CompressionMethod, ZipArchive, ZipWriter};

const ARGS_FILE: &str = "kepubify.args";

fn parity_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/parity")
}

fn options_from_args(args: &[String]) -> Options {
    let mut options = Options::default();
    let mut args = args.iter();
    while let Some(arg) = args.next() {
        let mut value = || args.next().expect("flag value").clone();
        match arg.as_str() {
            "--smarten-punctuation" => options.smart_punctuation = true,
            "--hyphenate" => options.hyphenate = Some(true),
            "--no-hyphenate" => options.hyphenate = Some(false),
            "--fullscreen-reading-fixes" => options.fullscreen_fixes = true,
            "--add-dummy-titlepage" => options.dummy_titlepage = Some(true),
            "--no-add-dummy-titlepage" => options.dummy_titlepage = Some(false),
            "--css" | "-c" => options.extra_css.push(value()),
            "--replace" | "-r" => {
                let pair = value();
                let (find, replace) = pair.split_once('|').expect("find|replace");
                options
                    .replacements
                    .push((find.to_owned(), replace.to_owned()));
            }
            "--charset" => {
                options.charset = match value().to_lowercase().as_str() {
                    "utf-8" => Charset::Utf8,
                    "auto" => Charset::Auto,
                    label => Charset::Label(label.to_owned()),
                }
            }
            other => panic!("unsupported kepubify flag {other}"),
        }
    }
    options
}

fn files_under(dir: &Path) -> Vec<PathBuf> {
    let mut files = Vec::new();
    for entry in fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        if path.is_dir() {
            files.extend(files_under(&path));
        } else {
            files.push(path);
        }
    }
    files.sort();
    files
}

fn zip_case(dir: &Path) -> Vec<u8> {
    let mut writer = ZipWriter::new(Cursor::new(Vec::new()));
    let stored = SimpleFileOptions::default().compression_method(CompressionMethod::Stored);
    writer.start_file("mimetype", stored).unwrap();
    writer
        .write_all(&fs::read(dir.join("mimetype")).unwrap())
        .unwrap();
    for path in files_under(dir) {
        let name = path
            .strip_prefix(dir)
            .unwrap()
            .to_str()
            .unwrap()
            .replace('\\', "/");
        if name == "mimetype" || name == ARGS_FILE {
            continue;
        }
        writer
            .start_file(name, SimpleFileOptions::default())
            .unwrap();
        writer.write_all(&fs::read(&path).unwrap()).unwrap();
    }
    writer.finish().unwrap().into_inner()
}

fn entries(archive: &[u8]) -> (Vec<String>, BTreeMap<String, Vec<u8>>) {
    let mut zip = ZipArchive::new(Cursor::new(archive)).unwrap();
    let mut order = Vec::new();
    let mut map = BTreeMap::new();
    for i in 0..zip.len() {
        let mut file = zip.by_index(i).unwrap();
        let mut bytes = Vec::new();
        file.read_to_end(&mut bytes).unwrap();
        order.push(file.name().to_owned());
        map.insert(file.name().to_owned(), bytes);
    }
    (order, map)
}

/// Describes every difference between our archive and kepubify's.
fn compare(ours: &[u8], theirs: &[u8]) -> Vec<String> {
    let (order, ours) = entries(ours);
    let (_, theirs) = entries(theirs);
    let mut problems = Vec::new();
    if order.first().map(String::as_str) != Some("mimetype") {
        problems.push("mimetype is not the first entry".to_owned());
    }
    for name in theirs.keys().filter(|n| !ours.contains_key(*n)) {
        problems.push(format!("missing entry {name}"));
    }
    for name in ours.keys().filter(|n| !theirs.contains_key(*n)) {
        problems.push(format!("unexpected entry {name}"));
    }
    for (name, expected) in &theirs {
        let Some(actual) = ours.get(name) else {
            continue;
        };
        if actual != expected {
            problems.push(format!(
                "{name} differs:\n{}",
                first_difference(actual, expected)
            ));
        }
    }
    problems
}

fn first_difference(actual: &[u8], expected: &[u8]) -> String {
    let at = actual
        .iter()
        .zip(expected)
        .position(|(a, b)| a != b)
        .unwrap_or(actual.len().min(expected.len()));
    let excerpt = |bytes: &[u8]| {
        let start = at.saturating_sub(120);
        let end = (at + 120).min(bytes.len());
        String::from_utf8_lossy(&bytes[start..end]).into_owned()
    };
    format!(
        "  at byte {at} (ours {} bytes, kepubify {} bytes)\n  ours:     {:?}\n  kepubify: {:?}",
        actual.len(),
        expected.len(),
        excerpt(actual),
        excerpt(expected)
    )
}

#[test]
fn parity_with_kepubify() {
    let dir = parity_dir();
    let mut cases: Vec<PathBuf> = fs::read_dir(dir.join("cases"))
        .unwrap()
        .map(|e| e.unwrap().path())
        .collect();
    cases.sort();
    assert!(!cases.is_empty());

    let mut report = Vec::new();
    for case in &cases {
        let name = case.file_name().unwrap().to_str().unwrap();
        let args: Vec<String> = fs::read_to_string(case.join(ARGS_FILE))
            .map(|s| s.lines().map(str::to_owned).collect())
            .unwrap_or_default();
        let expected = fs::read(dir.join("expected").join(format!("{name}.kepub.epub")))
            .unwrap_or_else(|_| {
                panic!("no kepubify output for {name}, run tests/parity/update.sh")
            });

        let mut output = Cursor::new(Vec::new());
        convert_with(
            Cursor::new(zip_case(case)),
            &mut output,
            &options_from_args(&args),
        )
        .unwrap();
        for problem in compare(&output.into_inner(), &expected) {
            report.push(format!("[{name}] {problem}"));
        }
    }
    assert!(
        report.is_empty(),
        "{} difference(s) with kepubify:\n{}",
        report.len(),
        report.join("\n")
    );
}

#[test]
#[ignore = "needs KEPUBIFY and KEPUB_CORPUS"]
fn parity_with_kepubify_on_corpus() {
    let kepubify = std::env::var("KEPUBIFY").expect("KEPUBIFY: path to the kepubify binary");
    let corpus = std::env::var("KEPUB_CORPUS").expect("KEPUB_CORPUS: directory of .epub files");
    let scratch = std::env::temp_dir().join(format!("relio-kepub-parity-{}", std::process::id()));
    fs::create_dir_all(&scratch).unwrap();

    let books: Vec<PathBuf> = files_under(Path::new(&corpus))
        .into_iter()
        .filter(|p| {
            let name = p.to_string_lossy().to_lowercase();
            name.ends_with(".epub") && !name.ends_with(".kepub.epub")
        })
        .collect();
    let (mut agreeing, mut report) = (0, Vec::new());
    for (i, book) in books.iter().enumerate() {
        let reference = scratch.join(format!("{i}.kepub.epub"));
        let theirs = Command::new(&kepubify)
            .arg("-o")
            .arg(&reference)
            .arg(book)
            .output()
            .unwrap();
        let mut output = Cursor::new(Vec::new());
        let ours = convert_with(
            Cursor::new(fs::read(book).unwrap()),
            &mut output,
            &Options::default(),
        );
        let problems = match (theirs.status.success(), ours) {
            (false, Err(_)) => Vec::new(),
            (false, Ok(_)) => vec!["kepubify rejects this book, we convert it".to_owned()],
            (true, Err(e)) => vec![format!("kepubify converts this book, we fail: {e}")],
            (true, Ok(_)) => compare(&output.into_inner(), &fs::read(&reference).unwrap()),
        };
        if problems.is_empty() {
            agreeing += 1;
        } else {
            report.push(format!("{}:\n{}", book.display(), problems.join("\n")));
        }
    }
    fs::remove_dir_all(&scratch).ok();
    eprintln!(
        "{agreeing}/{} books identical to kepubify (or rejected by both)",
        books.len()
    );
    assert!(report.is_empty(), "{}", report.join("\n\n"));
}
